<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');
$pid=(int)($_GET['petugas_id']??0);require_selected_petugas($pid);$uid=(int)current_user()['id_user'];$q=$pdo->prepare("SELECT p.*,k.nama_kegiatan,k.tujuan_akhir,k.status status_kegiatan,k.tanggal_mulai,k.tanggal_selesai FROM petugas p JOIN kegiatan k ON k.id_kegiatan=p.id_kegiatan WHERE p.id_petugas=? AND p.id_user=? AND p.deleted_at IS NULL");$q->execute([$pid,$uid]);$p=$q->fetch();if(!$p){http_response_code(403);exit('Identitas petugas tidak valid.');}if($p['status_kegiatan']!=='aktif'){http_response_code(403);exit('Kegiatan nonaktif. Progress tidak dapat ditambah atau diubah.');}
$id=(int)($_GET['id']??0);$progress=null;$details=[];if($id){$s=$pdo->prepare('SELECT * FROM progress_harian WHERE id_progress=? AND id_petugas=? AND id_kegiatan=?');$s->execute([$id,$pid,$p['id_kegiatan']]);$progress=$s->fetch();if(!$progress){http_response_code(404);exit('Progress tidak ditemukan.');}$s=$pdo->prepare('SELECT * FROM detail_progress WHERE id_progress=? ORDER BY id_detail');$s->execute([$id]);$details=$s->fetchAll();}
$desa=json_decode(file_get_contents(__DIR__.'/../../data/desa_sls.json'),true)?:[];$sub=json_decode(file_get_contents(__DIR__.'/../../data/sub_sls.json'),true)?:[];$hasLPD=in_array($p['tujuan_akhir'],['lpd','keduanya'],true);page_header($id?'Edit Progress Harian':'Input Progress Harian');
?>
<div class="card p-4 mb-3"><div class="d-flex justify-content-between flex-wrap"><div><div class="muted-label">Identitas Petugas</div><h2 class="h5 fw-bold mb-1"><?=e($p['nama_petugas'])?></h2><div class="text-secondary"><?=e($p['kecamatan'])?> · <?=e($p['nama_kegiatan'])?></div></div><a class="btn btn-light" href="<?=APP_BASE_URL?>/petugas/progress/index.php?id=<?=$pid?>">Kembali</a></div></div>
<form method="post" action="<?=APP_BASE_URL?>/petugas/progress/save.php" enctype="multipart/form-data" class="card p-4" id="progressForm"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="petugas_id" value="<?=$pid?>"><input type="hidden" name="id_progress" value="<?=$id?>"><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label">Tanggal Kegiatan</label><input type="date" name="tanggal" class="form-control" min="<?=e($p['tanggal_mulai'])?>" max="<?=e($p['tanggal_selesai'])?>" value="<?=e($progress['tanggal']??date('Y-m-d'))?>" required></div><div class="col-md-8"><label class="form-label">Kecamatan Penugasan</label><input class="form-control" value="<?=e($p['kecamatan'])?>" readonly></div></div><div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="h5 fw-bold mb-1">Detail Lokasi dan Kegiatan</h3><p class="text-secondary small mb-0">Satu tanggal dapat memuat beberapa SLS.</p></div><button type="button" class="btn btn-outline-primary btn-sm" id="addDetail">+ Tambah Detail SLS</button></div><div id="detailsWrap"><?php foreach($details as $i=>$d):?><div class="detail-item border rounded-3 p-3 mb-3"><input type="hidden" name="details[<?=$i?>][id_detail]" value="<?=$d['id_detail']?>"><div class="d-flex justify-content-between mb-2"><strong>Detail #<?=$i+1?></strong><button type="button" class="btn btn-sm btn-outline-danger remove-detail">Hapus</button></div><div class="row g-2"><div class="col-md-4"><label class="form-label">Desa/Kelurahan</label><select class="form-select desa" name="details[<?=$i?>][desa]" required><option value="">Pilih desa</option><?php foreach(array_keys($desa[strtoupper($p['kecamatan'])]??[]) as $v):?><option value="<?=e($v)?>" <?=$v===$d['desa']?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">SLS</label><select class="form-select sls" name="details[<?=$i?>][sls]" required><option value="<?=e($d['sls'])?>"><?=e($d['sls'])?></option></select></div><div class="col-md-4"><label class="form-label">Sub SLS (opsional)</label><select class="form-select sub" name="details[<?=$i?>][sub_sls]"><option value="">Tidak ada / pilih Sub SLS</option><?php foreach(($sub[strtoupper($p['kecamatan'])][$d['desa']][$d['sls']]??[]) as $v):?><option value="<?=e($v)?>" <?=$v===$d['sub_sls']?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Jam Mulai</label><input type="time" class="form-control" name="details[<?=$i?>][jam_mulai]" value="<?=e($d['jam_mulai'])?>" required></div><div class="col-md-3"><label class="form-label">Jam Selesai</label><input type="time" class="form-control" name="details[<?=$i?>][jam_selesai]" value="<?=e($d['jam_selesai'])?>" required></div><?php if($hasLPD):?><div class="col-12"><label class="form-label">Uraian Kegiatan</label><textarea class="form-control" name="details[<?=$i?>][uraian_kegiatan]" rows="2" required><?=e($d['uraian_kegiatan'])?></textarea></div><div class="col-md-4"><label class="form-label">Permasalahan</label><textarea class="form-control" name="details[<?=$i?>][permasalahan]" rows="2"><?=e($d['permasalahan'])?></textarea></div><div class="col-md-4"><label class="form-label">Pemecahan Masalah</label><textarea class="form-control" name="details[<?=$i?>][pemecahan_masalah]" rows="2"><?=e($d['pemecahan_masalah'])?></textarea></div><div class="col-md-4"><label class="form-label">Output/Tujuan</label><textarea class="form-control" name="details[<?=$i?>][output_tujuan]" rows="2" required><?=e($d['output_tujuan'])?></textarea></div><div class="col-12"><label class="form-label">Dokumentasi (JPG/PNG, maks. 250 KB per foto, maks. 5 foto)</label><input type="file" class="form-control" name="photos[<?=$i?>][]" accept="image/jpeg,image/png" multiple></div><?php endif;?></div></div><?php endforeach;?></div><div class="d-flex justify-content-end gap-2"><a class="btn btn-light" href="<?=APP_BASE_URL?>/petugas/progress/index.php?id=<?=$pid?>">Batal</a><button class="btn btn-primary">Simpan Progress</button></div></form>
<script>const desaData=<?=json_encode($desa[strtoupper($p['kecamatan'])]??[],JSON_UNESCAPED_UNICODE)?>;const subData=<?=json_encode($sub[strtoupper($p['kecamatan'])]??[],JSON_UNESCAPED_UNICODE)?>;const hasLPD=<?=$hasLPD?'true':'false'?>;let seq=<?=count($details)?>;function opts(sel,arr,placeholder){sel.innerHTML='<option value="">'+placeholder+'</option>';const vals=Array.isArray(arr)?arr:Object.keys(arr||{});vals.forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=v;sel.appendChild(o)});}function bindCard(card){let d=card.querySelector('.desa'),s=card.querySelector('.sls'),u=card.querySelector('.sub');d.addEventListener('change',()=>{opts(s,desaData[d.value]||[],'Pilih SLS');opts(u,{},'Tidak ada / pilih Sub SLS')});s.addEventListener('change',()=>opts(u,subData[d.value]?.[s.value]||[],'Tidak ada / pilih Sub SLS'));}document.querySelectorAll('.detail-item').forEach(bindCard);document.getElementById('addDetail').addEventListener('click',()=>{let i=seq++,html=`<div class="detail-item border rounded-3 p-3 mb-3"><div class="d-flex justify-content-between mb-2"><strong>Detail #${i+1}</strong><button type="button" class="btn btn-sm btn-outline-danger remove-detail">Hapus</button></div><div class="row g-2"><div class="col-md-4"><label class="form-label">Desa/Kelurahan</label><select class="form-select desa" name="details[${i}][desa]" required><option value="">Pilih desa</option></select></div><div class="col-md-4"><label class="form-label">SLS</label><select class="form-select sls" name="details[${i}][sls]" required><option value="">Pilih SLS</option></select></div><div class="col-md-4"><label class="form-label">Sub SLS (opsional)</label><select class="form-select sub" name="details[${i}][sub_sls]"><option value="">Tidak ada / pilih Sub SLS</option></select></div><div class="col-md-3"><label class="form-label">Jam Mulai</label><input type="time" class="form-control" name="details[${i}][jam_mulai]" required></div><div class="col-md-3"><label class="form-label">Jam Selesai</label><input type="time" class="form-control" name="details[${i}][jam_selesai]" required></div>${hasLPD?`<div class="col-12"><label class="form-label">Uraian Kegiatan</label><textarea class="form-control" name="details[${i}][uraian_kegiatan]" rows="2" required></textarea></div><div class="col-md-4"><label class="form-label">Permasalahan</label><textarea class="form-control" name="details[${i}][permasalahan]" rows="2"></textarea></div><div class="col-md-4"><label class="form-label">Pemecahan Masalah</label><textarea class="form-control" name="details[${i}][pemecahan_masalah]" rows="2"></textarea></div><div class="col-md-4"><label class="form-label">Output/Tujuan</label><textarea class="form-control" name="details[${i}][output_tujuan]" rows="2" required></textarea></div><div class="col-12"><label class="form-label">Dokumentasi (JPG/PNG, maks. 250 KB per foto, maks. 5 foto)</label><input type="file" class="form-control" name="photos[${i}][]" accept="image/jpeg,image/png" multiple></div>`:''}</div></div>`;let box=document.createElement('div');box.innerHTML=html;let card=box.firstElementChild;document.getElementById('detailsWrap').appendChild(card);bindCard(card)});document.getElementById('detailsWrap').addEventListener('click',e=>{if(e.target.classList.contains('remove-detail')){if(document.querySelectorAll('.detail-item').length>1)e.target.closest('.detail-item').remove();else alert('Minimal satu detail SLS.')}});</script>
